// Initialize the React state manager with your config, store, context and hooks
const { store, context, hooks } = manageReactState({
  // --- Store configuration ---------------------------------------------
  initialState: initialStateObject,          // your initial state object
  reducers: reducersMap,                    // map of reducer functions
  middlewares: [loggerMiddleware],          // logger middleware
  enhancers: [applyMiddleware('myMiddleWare')], // enhancer that applies your middleware

  // --- Store, context and hooks to expose to the component tree -------
  store: 'store',                           // (or whatever identifier you use)
  context: 'context',                       // (or whatever identifier you use)
  hooks: {                                   // custom hooks for components
    useStateSelectorHook,
    useDispatchActionHook
  }
});
```

This single line creates the store, context and hooks that you can then use throughout your React application.

